/**
 * Optional photo upload for a maintenance request.
 *
 * Security measures:
 *  - only JPEG, PNG and WebP are accepted (MIME type and extension are checked)
 *  - the file size is capped (default 2 MB, from MAX_UPLOAD_BYTES)
 *  - the stored filename is generated by the server, so a malicious filename
 *    cannot be used for path traversal (e.g. "../../server.js")
 *  - files are written outside the web root and are only served through an
 *    authenticated API route.
 */
import multer from 'multer';
import fs from 'node:fs';
import path from 'node:path';
import crypto from 'node:crypto';
import { config } from '../config.js';
import { ApiError } from '../utils/ApiError.js';

fs.mkdirSync(config.uploadDir, { recursive: true });

const EXTENSIONS = { 'image/jpeg': '.jpg', 'image/png': '.png', 'image/webp': '.webp' };

const storage = multer.diskStorage({
  destination: (req, file, cb) => cb(null, config.uploadDir),
  filename: (req, file, cb) => {
    const safeName = crypto.randomBytes(16).toString('hex') + EXTENSIONS[file.mimetype];
    cb(null, safeName);
  }
});

function fileFilter(req, file, cb) {
  const extensionOk = ['.jpg', '.jpeg', '.png', '.webp'].includes(
    path.extname(file.originalname).toLowerCase()
  );
  if (!config.allowedImageTypes.includes(file.mimetype) || !extensionOk) {
    return cb(ApiError.badRequest('Only JPG, PNG or WebP images can be uploaded.'));
  }
  cb(null, true);
}

const multerUpload = multer({
  storage,
  fileFilter,
  limits: { fileSize: config.maxUploadBytes, files: 1 }
});

/** Wraps multer so its errors become friendly ApiError messages. */
export function uploadPhoto(req, res, next) {
  multerUpload.single('photo')(req, res, (err) => {
    if (!err) return next();
    if (err instanceof multer.MulterError) {
      if (err.code === 'LIMIT_FILE_SIZE') {
        const mb = (config.maxUploadBytes / (1024 * 1024)).toFixed(0);
        return next(ApiError.badRequest(`The photo is too large. Maximum size is ${mb} MB.`));
      }
      return next(ApiError.badRequest('The photo could not be uploaded.'));
    }
    next(err);
  });
}

/** Delete an uploaded file again if the request could not be saved. */
export function discardUpload(file) {
  if (!file) return;
  fs.unlink(path.join(config.uploadDir, file.filename), () => {});
}
